async page => {
  const base='http://127.0.0.1:4193';
  await page.setViewportSize({width:1366,height:768});
  const routes=[['/pcs/testing/orders','[data-pcs-testing-order-list]'],['/pcs/testing/orders/create','[data-testing-create-page]'],['/pcs/products/styles/style_demand_PRJ_202603_006','[data-product-information]'],['/pcs/products/styles','main'],['/pcs/testing/orders/to_seed_normal','main h1']];
  const ready=async(selector)=>{
    await page.locator(selector).first().waitFor({state:'visible'});
    return await page.evaluate(async(sel)=>{
      const node=document.querySelector('main');
      const imgs=[...node.querySelectorAll('img')].filter(img=>img.getBoundingClientRect().top<innerHeight && img.getBoundingClientRect().bottom>0);
      await Promise.all(imgs.map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.addEventListener('load',resolve,{once:true});img.addEventListener('error',resolve,{once:true})})));
      await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
      return {ms:performance.now(),images:imgs.length,failed:imgs.filter(img=>!img.naturalWidth).length,overflow:document.documentElement.scrollWidth>innerWidth};
    },selector)
  };
  const cdp=await page.context().newCDPSession(page);
  const loads=[];
  for(const [path,selector] of routes){
    await cdp.send('Network.enable');await cdp.send('Network.setCacheDisabled',{cacheDisabled:true});
    for(let i=0;i<5;i++){await page.goto(base+path);loads.push({path,mode:'cache-disabled',sample:i,...await ready(selector)});}
    await cdp.send('Network.setCacheDisabled',{cacheDisabled:false});
    for(let i=0;i<5;i++){await page.reload();loads.push({path,mode:'reload',sample:i,...await ready(selector)});}
  }
  return {loads,max:Math.max(...loads.map(x=>x.ms)),browser:await page.context().browser().version()};
}

