async page => {
 const base='http://127.0.0.1:4193', actions=[], widths=[], checks=[], detailUrls=[];
 const snapshot=await page.evaluate(()=>Object.fromEntries(Object.entries(localStorage)));
 const install=()=>{window.__bindingStart=null; for(const name of ['click','input','change','keydown']) document.addEventListener(name,()=>{window.__bindingStart??=performance.now()},true)};
 await page.context().addInitScript(install); await page.evaluate(install);
 const settle=async(selector)=>{await page.locator(selector).first().waitFor({state:'visible'});return await page.evaluate(async(sel)=>{
  const node=document.querySelector(sel);const imgs=node.matches('img')?[node]:[...node.querySelectorAll('img')];
  await Promise.all(imgs.map(img=>img.complete?Promise.resolve():new Promise(r=>{img.addEventListener('load',r,{once:true});img.addEventListener('error',r,{once:true})})));
  await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
  return {ms:window.__bindingStart===null?null:performance.now()-window.__bindingStart,failed:imgs.filter(img=>!img.naturalWidth).length};
 },selector)};
 const measure=async(name,fn,selector,check)=>{await page.evaluate(()=>window.__bindingStart=null);await fn();if(check)await check();const result=await settle(selector);if(result.ms===null)throw Error('missing event '+name);actions.push({name,...result});};
 const assert=(value,message)=>{if(!value)throw Error(message);checks.push(message)};
 try {
 await page.goto(base+'/pcs/testing/orders');await settle('[data-pcs-testing-order-list]');
 const detail='通过建单结果打开';
 for(let i=0;i<5;i++){
   await page.reload();await settle('[data-pcs-testing-order-list]');
   await measure('列表进入新建',()=>page.getByRole('link',{name:'新建测款单',exact:true}).click(),'[data-testing-create-page]');
   await measure('未选商品阻断',()=>page.getByRole('button',{name:'创建测款单',exact:true}).click(),'[data-testing-create-feedback]',async()=>{await page.getByText('请选择商品档案。',{exact:true}).waitFor()});
   await measure('切换商品带出买手和属性',()=>page.locator('#testing-create-style').selectOption('style_demand_PRJ_202603_006'),'[data-testing-create-product]');
   assert((await page.locator('[data-testing-create-buyer]').innerText())==='陈刚','商品006买手自动带出');
   assert((await page.locator('[data-testing-create-page] input:not([type=checkbox]), [data-testing-create-page] select:not(#testing-create-style)').count())===0,'建单无买手或属性编辑控件');
   assert(!(await page.locator('[data-product-information]').innerText()).includes('待完善'),'全部商品信息已展示');
   for(const box of await page.locator('[data-testing-create-field=sku]').all())await measure('SKU取消选择',()=>box.uncheck(),'[data-testing-create-product]');
   await measure('空SKU阻断',()=>page.getByRole('button',{name:'创建测款单',exact:true}).click(),'[data-testing-create-feedback]',async()=>{await page.getByText('请至少选择一个测款 SKU。',{exact:true}).waitFor()});
   await measure('SKU选择',()=>page.locator('[data-testing-create-field=sku]').first().check(),'[data-testing-create-product]');
   await measure('商品大图打开',()=>page.getByRole('button',{name:'查看商品大图',exact:true}).click(),'[data-pda-image-preview-root] img');
   await measure('大图Esc关闭',()=>page.keyboard.press('Escape'),'[data-testing-create-product]');
   await measure('SKU大图打开',()=>page.locator('[data-testing-create-product] [data-pda-image-preview-url]').nth(1).click(),'[data-pda-image-preview-root] img');
   await measure('大图按钮关闭',()=>page.locator('[data-pda-image-preview-root]').getByRole('button',{name:'关闭',exact:true}).click(),'[data-testing-create-product]');
   await measure('查看关联商品档案',()=>page.getByRole('link',{name:'查看商品档案',exact:true}).click(),'[data-product-information]');
   await measure('打开商品属性维护',()=>page.getByRole('button',{name:'维护商品信息',exact:true}).click(),'[data-product-info-buyer]');
   for(const dimension of ['brands','categories','styles','trendElements','fabrics','crowds','ages','crowdPositioning','productPositioning','styleCodes']) {
     const select=page.locator(`[data-product-info-config="${dimension}"]`);
     const value=await select.locator('option:not([disabled])').evaluateAll(options=>options.find(o=>o.value)?.value);
     await measure('档案配置选择-'+dimension,()=>select.selectOption(value),'[data-product-information]');
   }
   await measure('档案商品买手绑定',()=>page.locator('[data-product-info-buyer]').selectOption('user-chengang'),'[data-product-information]');
   await measure('档案类目选择',()=>page.locator('[data-product-info-category]').selectOption('product-category-13'),'[data-product-information]');
   await measure('档案商品类型输入',()=>page.locator('#product-info-productType').fill('成衣'),'[data-product-information]');
   await measure('档案材质类型选择',()=>page.locator('[data-product-info-field=materialType][value="非毛织"]').click(),'[data-product-information]');
   await measure('保存商品信息',()=>page.getByRole('button',{name:'保存商品信息',exact:true}).click(),'[data-product-information]',async()=>{await page.getByRole('button',{name:'维护商品信息',exact:true}).waitFor()});
   await measure('再次维护',()=>page.getByRole('button',{name:'维护商品信息',exact:true}).click(),'[data-product-info-buyer]');
   await measure('取消维护',()=>page.locator('[data-product-information]').getByRole('button',{name:'取消',exact:true}).click(),'[data-product-information]');
   await page.goto(base+'/pcs/testing/orders/create');await settle('[data-testing-create-page]');
   await measure('切换另一商品',()=>page.locator('#testing-create-style').selectOption('style_demand_PRJ_202603_005'),'[data-testing-create-product]');
   assert((await page.locator('[data-testing-create-buyer]').innerText())!=='陈刚','不同商品切换不同买手');
   await measure('取消建单返回列表',()=>page.getByRole('link',{name:'取消',exact:true}).click(),'[data-pcs-testing-order-list]');
 }
 // 每次创建选择不同商品，验证保存结果与详情刷新。
 for(const num of ['006','005','004','003','002']){
   await page.getByRole('link',{name:'新建测款单',exact:true}).click();
   await page.locator('#testing-create-style').selectOption('style_demand_PRJ_202603_'+num);await settle('[data-testing-create-product]');
   const buyer=await page.locator('[data-testing-create-buyer]').innerText();
   await measure('创建成功并打开详情',()=>page.getByRole('button',{name:'创建测款单',exact:true}).click(),'main h1',async()=>{await page.waitForURL(/\/pcs\/testing\/orders\/(?!create)[^/]+$/)});
   await measure('详情展开商品信息',()=>page.getByText('商品信息（来自商品档案）',{exact:true}).click(),'[data-product-information]');
   detailUrls.push(page.url());assert((await page.locator('main').innerText()).includes('买手 '+buyer),'详情读取商品买手');
   await page.reload();await settle('main h1');assert((await page.locator('main').innerText()).includes('买手 '+buyer),'刷新后买手一致');
   await page.goto(base+'/pcs/testing/orders');await settle('[data-pcs-testing-order-list]');
 }
 for(const size of [{width:1366,height:768},{width:1280,height:720}]){
   await page.setViewportSize(size);
   await page.goto(base+'/pcs/testing/orders');await settle('[data-pcs-testing-order-list]');
   const list=await page.locator('[data-pcs-testing-order-list] h1').evaluate(n=>({left:n.getBoundingClientRect().left,right:n.parentElement.getBoundingClientRect().right}));
   await page.screenshot({path:`output/playwright/pcs-binding/list-${size.width}.png`});
   await page.getByRole('link',{name:'新建测款单',exact:true}).click();await settle('[data-testing-create-page]');
   const create=await page.locator('[data-testing-create-page] header').evaluate(n=>({left:n.getBoundingClientRect().left,right:n.getBoundingClientRect().right}));
   const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);
   widths.push({size,list,create,overflow});assert(Math.abs(list.left-create.left)<1 && Math.abs(list.right-create.right)<1,'列表与新建左右边界一致-'+size.width);
   await page.locator('#testing-create-style').selectOption('style_demand_PRJ_202603_007');await settle('[data-testing-create-product]');
   await page.screenshot({path:`output/playwright/pcs-binding/create-${size.width}.png`});
   await page.locator('[data-product-information]').screenshot({path:`output/playwright/pcs-binding/information-${size.width}.png`});
 }
 return {actions,widths,checks,detail,detailUrls,max:Math.max(...actions.map(a=>a.ms))};
 } catch(error) {return {error:String(error),actions,widths,checks,detailUrls};} finally {await page.evaluate(s=>{localStorage.clear();Object.entries(s).forEach(([k,v])=>localStorage.setItem(k,v))},snapshot);await page.goto(base+'/pcs/testing/orders/create');}
}

