async page => {
 const base='http://127.0.0.1:4193',actions=[],checks=[];
 const before=await page.evaluate(()=>Object.fromEntries(Object.entries(localStorage)));
 const install=()=>{window.__bindingStart=null;for(const n of ['click','input','change','keydown'])document.addEventListener(n,()=>{window.__bindingStart??=performance.now()},true)};
 await page.context().addInitScript(install);await page.evaluate(install);
 const measure=async(name,fn,selector,text)=>{await page.evaluate(()=>window.__bindingStart=null);await fn();await page.locator(selector).first().waitFor({state:'visible'});if(text)await page.getByText(text,{exact:true}).waitFor(); const ms=await page.evaluate(async()=>{await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return performance.now()-window.__bindingStart});actions.push({name,ms});};
