  await page.waitForFunction(()=>{const img=document.querySelector('[data-create-style-image]');return img?.complete&&img.naturalWidth>0});
  await measure('返回列表链接',()=>page.getByRole('link',{name:'返回测款单列表',exact:true}).click(),'[data-pcs-testing-order-list]');
 }
 checks.push('未绑定买手阻断及恢复各5次','图片真实资源加载失败及恢复各5次');
