async page => {
 const actions=[],checks=[],downloads=[];page.setDefaultTimeout(5000);const snapshot=await page.evaluate(()=>Object.fromEntries(Object.entries(localStorage)));
 await page.goto('http://127.0.0.1:4193/pcs/testing/orders');await page.locator('[data-pcs-testing-order-list]').waitFor();
 await page.evaluate(()=>{for(const n of ['click','input','change'])document.addEventListener(n,()=>window.__listStart??=performance.now(),true)});
 const measure=async(name,fn,check)=>{await page.evaluate(()=>window.__listStart=null);await fn();if(check)await check();const ms=await page.evaluate(async()=>{await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return performance.now()-window.__listStart});actions.push({name,ms})};
 try {for(let i=0;i<5;i++){
  await measure('买手关键词输入',()=>page.locator('[data-pcs-testing-field=search]').fill('陈买手'));
